import {AREAS,BRANCHES,NODES,NODE_MAP,MACHINES,SKINS,OUTFITS,DRONES,FACILITY,RESEARCH} from './data.js';
import {initial,timeLabel} from './state.js';
const $=id=>document.getElementById(id);
const button=(text,action,attrs='',disabled=false,cls='')=>`<button data-action="${action}" ${attrs} ${disabled?'disabled':''} class="${cls}">${text}</button>`;
export class UI{
 constructor(state,world,activities){this.state=state;this.world=world;this.activities=activities;this.page='overview';this.treeType='main';this.selected='power-0';this.transform={x:20,y:20,scale:1};this.branch='power';this.opened=false;this.started=false;this.displayEnergy=state.s.energy;this.uiTimer=0;this.lastPrompt='';this.machineIndex=null;this.treeDragging=false;this.buy=1;this.pages=[['overview','HQ'],['factory','Factory'],['tree','Upgrade Lab'],['workers','Workers'],['bank','Bank'],['research','Research'],['warehouse','Warehouse'],['market','Market'],['rebirth','Rebirth'],['arcade','Arcade'],['skins','Skins'],['settings','Settings']];this.nav();this.events();state.on((type,data)=>this.signal(type,data));$('loadNote').textContent=state.loadError||'';this.paint();}
 notice(message){const t=document.createElement('div');t.className='toast';t.textContent=message;$('toasts').append(t);if($('toasts').children.length>4)$('toasts').firstChild.remove();setTimeout(()=>t.remove(),4400);}
 nav(){$('menuNav').innerHTML='';}
 open(page='overview'){this.page=page;this.opened=true;this.world.paused=true;this.world.keys={};document.exitPointerLock?.();$('menu').classList.remove('hidden');this.render();}
 close(){this.opened=false;this.world.paused=!this.started;$('menu').classList.add('hidden');$('dialog').close();this.machineIndex=null;this.world.keys={};this.world.restoreFocus?.();}
 dialog(html){this.world.paused=true;this.world.keys={};document.exitPointerLock?.();$('dialogBody').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
 closeDialog(){$('dialog').close();this.machineIndex=null;this.world.paused=this.opened||!this.started;}
 render(){this.nav();const names={overview:'Headquarters',factory:'Factory management',tree:'Upgrade Lab',workers:'Worker Office',bank:'Bank',research:'Research Centre',warehouse:'Warehouse',market:'Marketplace',rebirth:'Rebirth Chamber',arcade:'Arcade',skins:'Skin Store',travel:'Facility map',missions:'Missions',collection:'Collection',achievements:'Achievements',stats:'Statistics',settings:'Settings',control:'Factory network',drones:'Worker Office',challenges:'Challenge chamber'};$('menuTitle').textContent=names[this.page]||'Facility Management';$('menuContent').style.overflow=this.page==='tree'?'hidden':'auto';$('menuContent').innerHTML=this[this.page+'View']?.()||this.overviewView();if(this.page==='tree')this.bindTree();this.paint();}
  signal(type,data){if(type==='notice')this.notice(data);if(type==='pulse'){this.world.pulse(data.critical);this.floater(data.value,data.critical);}if(type==='damage')this.floater(data,true);if(type==='teleport'){this.activities.clear();this.world.teleport(data);}if(type==='result'){this.dialog(`<div class="eyebrow">ROUND COMPLETE</div><h2>${data.score?'A little closer to mastery.':'Another attempt awaits.'}</h2><p>${data.message}</p><div class="big mint">+${data.tokens} tokens</div><p>+${this.state.fmt(data.energy)} energy</p><div class="actions">${button('Return to facility','return','','','primary')}</div>`);}if(type==='interact')this.interact(data);if(type==='zone')$('areaLabel').textContent=data;if(type==='skill'&&this.opened&&this.page==='tree')this.render();}
 floater(value,crit=false){const p=document.createElement('div');p.className='floater'+(crit?' critical':'');p.textContent=(crit?'CRITICAL +':'+')+this.state.fmt(value);p.style.left=this.world.pointer.x+'px';p.style.top=(this.world.pointer.y-25)+'px';$('floaters').append(p);setTimeout(()=>p.remove(),1050);}
 interact(r){if(r.action==='locked'){const a=AREAS.find(a=>a.id===r.data),node=NODES.find(n=>n.effects[a.flag]);this.dialog(`<div class="eyebrow">FACILITY EXPANSION</div><h2>${a.name}</h2><p>Earn ${this.state.fmt(a.need)} energy this run and unlock <strong>${node.name}</strong> in Exploration.</p><div class="actions">${button('Close','closedialog')}${button('View required skill','requiredskill',`data-id="${node.id}"`,false,'primary')}</div>`);return;}if(['target','memory','boss','shield','relay','event'].includes(r.action))return;if(r.action==='core'){this.state.pulse();return;}if(r.action==='shard'){this.state.collect(r.data);return;}if(r.action==='secret'){this.state.secret(r.data);return;}if(r.action==='return'){this.activities.leave();return;}if(r.action==='machine'){this.world.focus?.(r);this.machineIndex=r.data;this.showMachine();return;}if(r.action==='npc'){this.showNPC(r.data);return;}if(r.action==='daily'){this.supplyDialog();return;}if(r.action==='travel'){this.open('travel');return;}this.world.focus?.(r);this.open(r.action);}
  overviewView(){const s=this.state.s,totalMachines=s.machines.reduce((a,b)=>a+b,0),research=s.research.reduce((a,b)=>a+b,0),facility=s.facility.reduce((a,b)=>a+b,0);return `<div class="hq-hero"><div class="metric-panel"><div class="metric-label">FACILITY LEVEL</div><div class="metric-value">${this.state.level}</div><p>Central overview only. Use the buildings in the world to manage individual systems.</p><div class="status-strip"><span class="status-chip good">${s.areas.length}/10 districts online</span><span class="status-chip">${totalMachines} machine levels</span><span class="status-chip">${research} research levels</span></div></div><div class="metric-panel"><div class="metric-label">TOTAL PRODUCTION</div><div class="metric-value">${this.state.fmt(this.state.cps)}/s</div><p>${this.state.fmt(s.lifetime)} lifetime energy generated.</p></div></div><div class="metrics-row"><div class="mini-metric"><small>CURRENT ENERGY</small><strong>${this.state.fmt(s.energy)}</strong></div><div class="mini-metric"><small>REBIRTHS</small><strong>${s.rebirths}</strong></div><div class="mini-metric"><small>RESEARCH</small><strong>${research}</strong></div><div class="mini-metric"><small>INFRASTRUCTURE</small><strong>${facility}</strong></div></div><div class="section-title">FACILITY STATUS</div><div class="grid"><div class="card"><h3>Expansion</h3><p>${s.areas.length} districts are operational. ${10-s.areas.length} remain locked behind facility progression.</p><div class="thin-bar"><i style="width:${s.areas.length*10}%"></i></div></div><div class="card"><h3>Workforce</h3><p>${s.equipped.length} / ${s.slots} automation specialists currently assigned.</p><div class="thin-bar"><i style="width:${Math.min(100,s.equipped.length/Math.max(1,s.slots)*100)}%"></i></div></div><div class="card"><h3>Collections</h3><p>${s.collected.length} / 50 energy shards recovered across the facility.</p><div class="thin-bar"><i style="width:${s.collected.length*2}%"></i></div></div></div>`;}
  treeView(){const s=this.state.s,tree=this.treeType,locked=tree==='quantum'&&!s.rebirths||tree==='ascension'&&!s.ascensions||tree==='mastery'&&this.state.level<100;return `<div class="tree-layout"><div class="tree-main"><div class="toolbar">${[['main','Skill tree'],['quantum','Quantum'],['ascension','Ascension'],['mastery','Mastery']].map(([id,name])=>button(name,'treetype',`data-id="${id}"`,false,tree===id?'selected':'')).join('')}<span style="flex:1"></span>${button('Respec','respec','','','small')}</div>${locked?`<div class="card tree-empty"><h2>${tree==='quantum'?'Rebirth once':tree==='ascension'?'Ascend once':'Reach level 100'}</h2><p>This tree becomes available at that milestone.</p></div>`:`<div class="tree-toolbar">${tree==='main'?BRANCHES.map(b=>button(b[1],'branch',`data-id="${b[0]}"`,false,this.branch===b[0]?'selected':'')).join('')+button('Shared','branch','data-id="cross"',false,this.branch==='cross'?'selected':''):''}${button('Fit','treefit')}${button('−','zoom','data-dir="-1"')}${button('+','zoom','data-dir="1"')}</div><div id="treeViewport" class="tree-viewport"><div id="treeInner" class="tree-inner">${this.treeGraph()}</div></div><div class="tree-help">Choose a branch above. Drag to see more. Click a node for its effect and cost.</div>`}</div><aside class="tree-inspector card" id="inspector">${this.inspector()}</aside></div>`;}
 treeGraph(){const tree=this.treeType,nodes=NODES.filter(n=>n.tree===tree&&(tree!=='main'||n.branch===this.branch)),s=this.state.s;const bi=BRANCHES.findIndex(b=>b[0]===this.branch);const pos=n=>tree==='main'&&this.branch!=='cross'?{x:90+(n.x-bi*350-36)*1.55,y:115+(n.y-140)*1.17}:tree==='main'?{x:100+(Number(n.id.split('-')[1])%3)*210,y:130+Math.floor(Number(n.id.split('-')[1])/3)*210}:{x:n.x,y:n.y};this.treeBox={width:Math.max(...nodes.map(n=>pos(n).x))+160,height:Math.max(...nodes.map(n=>pos(n).y))+160};let paths='';for(const n of nodes)for(const id of n.requires){const p=NODE_MAP[id];if(!nodes.includes(p))continue;const np=pos(n),pp=pos(p);paths+=`<path class="tree-path ${s.skills[id]?'on':''}" d="M${pp.x+32},${pp.y+64} C${pp.x+32},${(pp.y+np.y)/2+50} ${np.x+32},${(pp.y+np.y)/2} ${np.x+32},${np.y}"/>`;}const branch=BRANCHES[bi];return `<svg width="2200" height="1600">${paths}</svg>${tree==='main'?`<div class="branch-label" style="left:90px;top:25px">${branch?branch[1]:'Shared upgrades'}<small>${branch?branch[3]:'Powerful upgrades that connect multiple branches'}</small></div>`:''}${nodes.map(n=>{const l=s.skills[n.id]||0,available=this.state.available(n),currency=n.tree==='quantum'?'cores':n.tree==='ascension'?'shards':'points',p=pos(n);return `<button data-action="node" data-id="${n.id}" class="node ${l?'owned':''} ${available&&s[currency]>=this.state.nodeCost(n)?'available':''} ${l>=n.max?'maxed':''} ${n.keystone?'keystone':''} ${n.id===this.selected?'chosen':''}" style="left:${p.x}px;top:${p.y}px" title="${n.name} — ${n.desc}"><strong>${n.keystone?'✧':n.tree==='quantum'?'⬡':['ϟ','▦','◇','☾','⟳','⌁'][bi]||'✣'}</strong><small>${l}/${n.max>=1e6?'∞':n.max}</small><span class="node-label">${n.name}</span></button>`;}).join('')}`;}

 inspector(){let n=NODE_MAP[this.selected];if(!n||n.tree!==this.treeType){n=NODES.find(n=>n.tree===this.treeType);this.selected=n.id;}const s=this.state.s,l=s.skills[n.id]||0,currency=n.tree==='quantum'?'cores':n.tree==='ascension'?'shards':'points',available=this.state.available(n),cost=this.state.nodeCost(n);return `<div class="eyebrow" style="color:${n.color}">${n.keystone?'KEYSTONE':n.tree.toUpperCase()+' RESEARCH'}</div><div class="node-glyph" style="--node:${n.color}">${n.keystone?'✧':'⬡'}</div><h2>${n.name}</h2><p>${n.desc}</p><div class="tag">LEVEL ${l} / ${n.max>=1e6?'∞':n.max}</div><div class="section-title">Requirements</div>${n.requires.length?`<ul class="requirements">${n.requires.map(id=>`<li style="color:${s.skills[id]?'var(--accent)':'var(--muted)'}">${s.skills[id]?'✓':'○'} ${NODE_MAP[id].name} Lv. 1</li>`).join('')}</ul>`:'<p>Root node. Start your path here.</p>'}<div class="section-title">Research cost</div><h3>${cost} ${currency==='points'?'Skill Points':currency==='cores'?'Quantum Cores':'Singularity Shards'}</h3><p>${this.state.fmt(s[currency])} available</p>${button(l>=n.max?'Maxed':!available?'Prerequisites needed':'Unlock / upgrade','skillbuy',`data-id="${n.id}"`,!available||s[currency]<cost,'primary')}<p class="muted" style="font-size:10px">Skills remain after rebirth and ascension. New Reality resets them.</p>`;}
 applyTree(){const el=$('treeInner');if(el)el.style.transform=`translate(${this.transform.x}px,${this.transform.y}px) scale(${this.transform.scale})`;}
 bindTree(){const v=$('treeViewport');if(!v)return;this.applyTree();let drag=null;v.addEventListener('pointerdown',e=>{if(e.target.closest('.node'))return;drag={x:e.clientX,y:e.clientY,tx:this.transform.x,ty:this.transform.y};v.setPointerCapture(e.pointerId);});v.addEventListener('pointermove',e=>{if(!drag)return;this.transform.x=drag.tx+e.clientX-drag.x;this.transform.y=drag.ty+e.clientY-drag.y;this.applyTree();});v.addEventListener('pointerup',()=>drag=null);v.addEventListener('wheel',e=>{e.preventDefault();const r=v.getBoundingClientRect();this.zoom(e.deltaY<0?1.12:1/1.12,e.clientX-r.left,e.clientY-r.top);},{passive:false});}
 zoom(factor,x,y){const v=$('treeViewport');if(!v)return;x??=v.clientWidth/2;y??=v.clientHeight/2;const old=this.transform.scale,next=Math.max(.22,Math.min(1.8,old*factor));this.transform.x=x-(x-this.transform.x)*next/old;this.transform.y=y-(y-this.transform.y)*next/old;this.transform.scale=next;this.applyTree();}
 fitTree(){const v=$('treeViewport');if(!v)return;const {width:w,height:h}=this.treeBox;this.transform={x:20,y:20,scale:Math.min((v.clientWidth-40)/w,(v.clientHeight-40)/h,1.2)};this.applyTree();}
 travelView(){const s=this.state.s;return `<div class="notice-panel"><h3>Choose a plot to focus on.</h3><p>Plots open when you unlock their Exploration skill and earn enough energy this run. Click Focus to move the camera to any open plot. Room access resets at rebirth.</p></div><div class="grid">${AREAS.map(a=>{const open=s.areas.includes(a.id),node=a.flag?NODES.find(n=>n.effects[a.flag]):null;return `<div class="card ${open?'done':''}"><div class="eyebrow" style="color:${a.color}">${open?'ACCESS GRANTED':'LOCKED SECTOR'}</div><h3 style="margin-top:9px">${a.name}</h3><p>${a.subtitle}</p><div class="muted" style="font-size:11px">${a.need?`${this.state.fmt(a.need)} run energy + ${node?.name||'exploration research'}`:'Starting location'}</div><div class="cardfooter"><span class="tag">${s.discovered.includes(a.id)?'DISCOVERED':'UNKNOWN'}</span>${button('Focus','travel',`data-id="${a.id}"`,!open,'small')}</div></div>`}).join('')}</div>`;}
 showMachine(){const i=this.machineIndex,d=MACHINES[i],s=this.state.s,l=s.machines[i];this.dialog(`<div class="eyebrow">MACHINE CONTROL / ${d.area.toUpperCase()}</div><h2>${d.name}</h2><div class="big">LEVEL ${l}</div><p>${this.state.fmt(this.state.machineRate(i))} base energy/sec · ${this.state.milestone(l)}× milestone bonus</p><div class="thin-bar"><i style="width:${(l%10)*10}%"></i></div><p>Milestones at 10, 25, 50, 100, 250, 500 and 1,000 double production and evolve the machine.</p>${!this.state.fx.automation?'<p class="gold">Unlock Basic automation in the skill tree first.</p>':''}<div class="machine-bulk">${[1,10,100,'max'].map(n=>{const q=this.state.quote(i,n);return button(`×${n==='max'?'MAX':n} · ${this.state.fmt(q.cost)} ϟ`,'machinebuy',`data-i="${i}" data-n="${n}"`,!this.state.fx.automation||s.energy<q.cost||!q.n,'small');}).join('')}</div><div class="actions">${button('Close panel','closedialog')}</div>`);}

 factoryView(){const s=this.state.s,active=MACHINES.filter((m,i)=>s.areas.includes(m.area)&&s.machines[i]>0),input=active.length?active[0].name:'Energy feed',output=this.state.cps;return `<div class="production-chain"><div class="chain-stage"><small>INPUT</small><strong>${input}</strong><p>Raw energy enters the production network.</p></div><div class="chain-arrow">→</div><div class="chain-stage"><small>PROCESSING</small><strong>${active.length} active machines</strong><p>Automation converts energy through the current machine chain.</p></div><div class="chain-arrow">→</div><div class="chain-stage"><small>EFFICIENCY</small><strong>${Math.min(100,72+s.facility[1]*2)}%</strong><p>Power-grid and facility upgrades improve throughput.</p></div><div class="chain-arrow">→</div><div class="chain-stage"><small>OUTPUT</small><strong>${this.state.fmt(output)}/s</strong><p>Current passive facility production.</p></div></div><div class="status-strip">${!this.state.fx.automation?'<span class="status-chip warn">Automation locked</span>':'<span class="status-chip good">Production online</span>'}<span class="status-chip">${s.machines.reduce((a,b)=>a+b,0)} total machine levels</span><span class="status-chip">Power grid Lv ${s.facility[1]}</span></div><div class="toolbar">${[1,10,100,'max'].map(n=>button('×'+String(n).toUpperCase(),'bulk',`data-n="${n}"`,false,this.buy===n?'selected':'')).join('')}</div><div class="grid">${MACHINES.map((d,i)=>{const q=this.state.quote(i,this.buy),open=s.areas.includes(d.area),level=s.machines[i],rate=this.state.machineRate(i);return `<div class="card"><div class="row between"><div><div class="eyebrow">${d.area.toUpperCase()}</div><h3>${d.name}</h3></div><span class="tag">LV ${level}</span></div><p>${open?`${this.state.fmt(rate)} base energy/sec · ${this.state.milestone(level)}× milestone`:'District not yet connected to the factory network.'}</p><div class="cardfooter"><span class="mint">${this.state.fmt(q.cost)} energy</span>${button(open?(level?'Upgrade':'Build'):'Locked','machinebuy',`data-i="${i}" data-n="${this.buy}"`,!this.state.fx.automation||!open||s.energy<q.cost||!q.n,'small')}</div></div>`;}).join('')}</div>`;}
 bankView(){const s=this.state.s,offline=Math.floor(this.state.cps*this.state.offlineEfficiency*this.state.offlineHours*3600),series=Array.from({length:16},(_,i)=>{const x=i/15*100,y=70-(42+Math.sin(i*.82)*8+i*1.25);return `${x.toFixed(1)},${Math.max(8,Math.min(76,y)).toFixed(1)}`}).join(' ');return `<div class="bank-hero"><div class="metric-panel"><div class="metric-label">CURRENT ENERGY</div><div class="metric-value">${this.state.fmt(s.energy)}</div><div class="metrics-row" style="margin-top:14px"><div class="mini-metric"><small>INCOME / SECOND</small><strong>${this.state.fmt(this.state.cps)}</strong></div><div class="mini-metric"><small>INCOME / MINUTE</small><strong>${this.state.fmt(this.state.cps*60)}</strong></div><div class="mini-metric"><small>LIFETIME</small><strong>${this.state.fmt(s.lifetime)}</strong></div><div class="mini-metric"><small>OFFLINE CAPACITY</small><strong>${this.state.offlineHours}h</strong></div></div></div><div class="metric-panel"><div class="metric-label">PROJECTED PRODUCTION TREND</div><div class="bank-chart"><svg viewBox="0 0 100 80" preserveAspectRatio="none"><defs><linearGradient id="bankFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d7ac58" stop-opacity=".20"/><stop offset="1" stop-color="#d7ac58" stop-opacity="0"/></linearGradient></defs><polyline class="chart-line" points="${series}"/></svg></div></div></div><div class="grid"><div class="card"><div class="eyebrow">OFFLINE EARNINGS</div><h3>${this.state.fmt(offline)} max stored energy</h3><p>${Math.round(this.state.offlineEfficiency*100)}% efficiency for up to ${this.state.offlineHours} hours.</p></div><div class="card"><div class="eyebrow">FINANCIAL MULTIPLIER</div><h3>${(1+(this.state.fx.global||0)).toFixed(2)}× global modifier</h3><p>Permanent skills, research, rebirths and reality bonuses contribute to facility income.</p></div><div class="card"><div class="eyebrow">RUN EARNINGS</div><h3>${this.state.fmt(s.run)}</h3><p>Current-run earnings determine expansion and rebirth readiness.</p></div></div>`;}
 workersView(){const s=this.state.s,names=['Mara Voss','Jax Mercer','Iris Vale','Noah Chen','Vega Rook'],rarities=['COMMON','UNCOMMON','RARE','EPIC','LEGENDARY'];return `<div class="notice-panel"><div class="row between"><div><div class="eyebrow">STAFF CAPACITY</div><h3>${s.equipped.length} / ${s.slots} assigned</h3><p>Automation specialists are assigned to the facility network. Training uses three duplicate contracts and permanently improves their bonus.</p></div>${button('Add slot · 50 tokens','droneslot','',s.slots>=3||s.tokens<50,'small')}</div></div><div class="worker-grid">${DRONES.map((d,i)=>{const hired=s.droneCopies[i]>0,assigned=s.equipped.includes(i),eff=Math.min(99,68+i*5+s.droneLevels[i]*3);return `<div class="worker-card"><div class="worker-head"><div class="worker-avatar">${names[i].split(' ').map(x=>x[0]).join('')}</div><div><div class="eyebrow">${rarities[i]}</div><h3>${names[i]}</h3><span class="tag">LV ${1+s.droneLevels[i]}</span></div></div><div class="worker-stats"><div class="worker-stat"><small>EFFICIENCY</small><strong>${eff}%</strong></div><div class="worker-stat"><small>PRODUCTION BONUS</small><strong>${d[1]}</strong></div><div class="worker-stat"><small>CONTRACTS</small><strong>${s.droneCopies[i]}</strong></div><div class="worker-stat"><small>ASSIGNMENT</small><strong>${assigned?'Facility':'Unassigned'}</strong></div></div><div class="cardfooter">${button(hired?'Hire duplicate':`Hire · ${d[3]} dust`,'dronebuy',`data-i="${i}"`,s.dust<d[3],'small')}${button(assigned?'Remove':'Assign','droneequip',`data-i="${i}"`,!hired,'small')}${button('Train','dronefuse',`data-i="${i}"`,s.droneCopies[i]<3||s.droneLevels[i]>=10,'small')}</div></div>`}).join('')}</div>`;}
 warehouseView(){const s=this.state.s,used=Math.min(10000,Math.floor(Math.log10(Math.max(1,s.energy))*720+s.dust*8+s.tokens*4+s.cores*12)),capacity=10000+s.facility[3]*1200,percent=Math.min(100,used/capacity*100);return `<div class="storage-capacity"><div><div class="eyebrow">STORAGE CAPACITY</div><h2>${this.state.fmt(used)} / ${this.state.fmt(capacity)}</h2><div class="thin-bar"><i style="width:${percent}%"></i></div></div><span class="tag">${percent>85?'CAPACITY WARNING':'OPERATING NORMALLY'}</span></div><div class="inventory-grid">${[['ENERGY RESERVE',s.energy,'Primary production currency'],['STARDUST',s.dust,'Cosmetics and specialist contracts'],['QUANTUM CORES',s.cores,'Permanent rebirth research'],['ARCADE TOKENS',s.tokens,'Arcade exchange currency'],['SINGULARITY SHARDS',s.shards,'Ascension technology'],['ENERGY SHARDS',s.collected.length,'Recovered world fragments']].map(([n,v,d])=>`<div class="inventory-slot"><small>${n}</small><strong>${this.state.fmt(v)}</strong><p>${d}</p></div>`).join('')}</div><div class="section-title">WAREHOUSE SYSTEMS</div><div class="grid"><div class="card"><h3>Storage System · Lv ${s.facility[3]}</h3><p>Each infrastructure level extends offline storage by one hour. Current maximum: ${this.state.offlineHours} hours.</p>${button(`${this.state.fmt(1000*2**s.facility[3])} energy · Upgrade`,'facility','data-i="3"',s.energy<1000*2**s.facility[3]||s.facility[3]>=50,'small')}</div><div class="card"><h3>Logistics status</h3><p>${percent>85?'Storage is approaching its practical UI capacity. Upgrade storage infrastructure to increase headroom.':'All tracked resources are within normal operating capacity.'}</p></div></div>`;}
 marketView(){const s=this.state.s,phase=Math.floor(Date.now()/60000),rows=[['Stardust shipment',10000,'ENERGY','1 DUST',Math.sin(phase)*6,'dust'],['Arcade token crate',5,'DUST','10 TOKENS',Math.sin(phase+2)*9,'tokens'],['Energy futures',10,'TOKENS','50K ENERGY',Math.sin(phase+4)*7,'energy']];return `<div class="notice-panel"><h3>Facility marketplace</h3><p>Small internal exchanges let you rebalance resources. Prices are fixed for gameplay balance; the market-change indicator is a live sentiment display.</p></div><div class="market-table">${rows.map(([name,cost,cur,result,chg,id])=>{const own=cur==='ENERGY'?s.energy:cur==='DUST'?s.dust:s.tokens,ok=own>=cost;return `<div class="market-row"><div><small>ITEM</small><strong>${name}</strong></div><div><small>COST</small><strong>${this.state.fmt(cost)} ${cur}</strong></div><div><small>MARKET</small><strong class="${chg>=0?'price-up':'price-down'}">${chg>=0?'+':''}${chg.toFixed(1)}%</strong></div><div><small>RETURN</small><strong>${result}</strong></div>${button('Trade','markettrade',`data-id="${id}"`,!ok,'small')}</div>`}).join('')}</div>`;}
 skinsView(){const s=this.state.s;return `<div class="notice-panel"><div class="row between"><div><div class="eyebrow">COSMETICS SHOWROOM</div><h3>Reactor themes</h3><p>Select a visual signature for the core. Cosmetics persist through rebirth and ascension.</p></div><span class="tag">${s.dust} STARDUST</span></div></div><div class="showroom-grid">${SKINS.map(d=>`<div class="card showroom-card" style="--skin:${d[2]}"><div class="showroom-preview"></div><div class="row between"><span class="tag">${d[3]}</span><span class="muted">${d[4]<0?'DISCOVERY':d[4]+' DUST'}</span></div><h3>${s.skins.includes(d[0])?d[1]:d[4]<0?'Undiscovered theme':d[1]}</h3><p>${d[0]==='gold'?'+2% all energy while equipped.':'A cosmetic visual signature for your reactor.'}</p>${button(s.skin===d[0]?'Equipped':s.skins.includes(d[0])?'Equip':d[4]<0?'Locked':'Purchase','skin',`data-id="${d[0]}"`,s.skin===d[0]||!s.skins.includes(d[0])&&(d[4]<0||s.dust<d[4]),'small')}</div>`).join('')}</div>`;}
 controlView(){if(!this.state.s.areas.includes('research'))return '<div class="card"><h2>Open the Research Wing first.</h2><p>Click any machine on the map to build or upgrade it.</p></div>';return `<div class="toolbar">${[1,10,100,'max'].map(n=>button('×'+String(n).toUpperCase(),'bulk',`data-n="${n}"`,false,this.buy===n?'selected':'')).join('')}</div><div class="grid">${MACHINES.map((d,i)=>{const q=this.state.quote(i,this.buy),s=this.state.s;return `<div class="card"><div class="row between"><h3>${d.name}</h3><span class="tag">LV ${s.machines[i]}</span></div><p>${this.state.fmt(this.state.machineRate(i))} base energy/sec</p><div class="cardfooter"><span class="mint">${this.state.fmt(q.cost)} ϟ</span>${button('Buy ×'+q.n,'machinebuy',`data-i="${i}" data-n="${this.buy}"`,!this.state.fx.automation||!s.areas.includes(d.area)||s.energy<q.cost||!q.n)}</div></div>`;}).join('')}</div><div class="section-title">Facility infrastructure</div><div class="grid">${FACILITY.map((d,i)=>`<div class="card"><h3>${d[0]} · Lv ${this.state.s.facility[i]}</h3><p>${d[1]} per level.</p>${button(`${this.state.fmt(1000*2**this.state.s.facility[i])} energy`,'facility',`data-i="${i}"`,this.state.s.energy<1000*2**this.state.s.facility[i]||this.state.s.facility[i]>=50)}</div>`).join('')}</div>`;}
 researchView(){const s=this.state.s;return `<div class="notice-panel"><div class="row between"><div><div class="eyebrow">ACTIVE RESEARCH</div><h3>${s.researchJob?RESEARCH[s.researchJob.i][0]:'No project running'}</h3><p>${s.researchJob?`Completion in <span class="mint" data-research-time>${timeLabel((s.researchJob.end-Date.now())/1000)}</span>. Research continues while offline.`:'Select one technology branch below. Only one project can run at a time.'}</p></div><span class="tag">${s.research.reduce((a,b)=>a+b,0)} TOTAL LEVELS</span></div></div><div class="research-lanes">${RESEARCH.map((d,i)=>{const cost=d[2]*2**s.research[i];return `<div class="research-node"><div class="eyebrow">TECHNOLOGY ${String(i+1).padStart(2,'0')}</div><h3>${d[0]}</h3><span class="tag">LEVEL ${s.research[i]} / 20</span><p>${d[1]} per level.</p><div class="progress-label"><span>${d[3]} sec research time</span><span>${this.state.fmt(cost)} energy</span></div>${button(s.researchJob?'Research in progress':'Start research','researchbuy',`data-i="${i}"`,!!s.researchJob||s.energy<cost||s.research[i]>=20,'primary small')}</div>`}).join('')}</div>`;}
  arcadeView(){const locked=this.state.s.lifetime<1000,games=[['target','TARGET RANGE','30 seconds of precision targeting.','Rapid aim'],['memory','REACTOR MEMORY','Repeat increasingly long control sequences.','Pattern'],['catch','ENERGY CATCH','Guide the tray beneath falling crystals.','Control'],['parkour','REACTOR RELAY','Activate twelve relays in sequence.','Speed'],['boss','BOSS CHAMBER','Attack the boss and shield during warnings.','Combat']];return `<div class="notice-panel"><div class="row between"><div><div class="eyebrow">ARCADE FLOOR</div><h3>${locked?'Arcade locked':'Choose a minigame'}</h3><p>${locked?'Reach 1K lifetime energy to power the arcade.':'Games award energy and arcade tokens without replacing your facility progression.'}</p></div><span class="tag">${this.state.s.tokens} TOKENS</span></div></div><div class="grid">${games.map(([id,name,desc,type])=>`<div class="card arcade-card"><div class="eyebrow">${type.toUpperCase()}</div><h3>${name}</h3><p>${desc}</p><div class="play-spacer"></div><div class="cardfooter"><span class="muted">Best results saved in records</span>${button('Play','startgame',`data-id="${id}"`,locked||(id==='boss'&&this.state.s.rebirths<1),'primary small')}</div></div>`).join('')}</div><div class="section-title">ARCADE EXCHANGE</div><div class="grid">${[['all','2× Energy','Five minutes of doubled energy.',10],['click','5× Manual energy','60 seconds of overcharged pulses.',8],['xp','2× XP','Five minutes of accelerated learning.',15]].map(([id,name,desc,cost])=>`<div class="card"><h3>${name}</h3><p>${desc}</p>${button(cost+' tokens','tokenboost',`data-id="${id}"`,this.state.s.tokens<cost,'small')}</div>`).join('')}</div>`;}
  missionsView(){const s=this.state.s;this.state.calendar();return `<div class="notice-panel"><h3>Your next assignment is out there.</h3><p>Click the engineer in Origin, scientist in Research, technician in the Factory or explorer at Launch for special assignments.</p></div>${['daily','weekly'].map(period=>`<div class="section-title">${period} missions · ${period==='daily'?'00:00 UTC':'Monday 00:00 UTC'} reset</div><div class="grid">${this.state.missions().filter(m=>m[1]===period).map(m=>{const v=s.quests[period][m[2]]||0,done=s.quests.claims.includes(m[0]);return `<div class="card ${done?'done':''}"><h3>${m[4]}</h3><div class="progress-label"><span>${this.state.fmt(Math.min(v,m[3]))} / ${this.state.fmt(m[3])}</span><span>${period==='daily'?1:3} SP</span></div><div class="thin-bar"><i style="width:${Math.min(100,v/m[3]*100)}%"></i></div><div class="cardfooter">${button(done?'Claimed':'Claim reward','mission',`data-id="${m[0]}"`,done||v<m[3])}</div></div>`;}).join('')}</div>`).join('')}`;}
 showNPC(id){const q=this.state.npcTalk(id),v=this.state.npcValue(q),done=this.state.s.npcClaims.includes(id);this.dialog(`<div class="eyebrow">FACILITY ASSIGNMENT</div><h2>${q[1]}</h2><p>“${q[2]}. A little progress today goes a long way tomorrow.”</p><div class="progress-label"><span>${this.state.fmt(Math.min(v,q[4]))} / ${this.state.fmt(q[4])}</span><span>${done?'Complete':'In progress'}</span></div><div class="thin-bar"><i style="width:${Math.min(100,v/q[4]*100)}%"></i></div><p>Reward: 3 Skill Points · 15 stardust · 100 base XP</p><div class="actions">${button('Goodbye','closedialog')}${button(done?'Claimed':'Complete assignment','npcclaim',`data-id="${id}"`,done||v<q[4],'primary')}</div>`);}
 supplyDialog(){this.dialog(`<div class="eyebrow">DAILY SUPPLY</div><h2>A little help from the stars.</h2><p>Day 1: energy · Day 2: boost · Day 3: XP · Day 4: tokens · Day 5: drone · Day 6: quantum core · Day 7: Galaxy skin + 25 stardust.</p><div class="actions">${button('Later','closedialog')}${button(this.state.s.daily.date===this.state.calendar()?'Collected':'Collect','daily','',this.state.s.daily.date===this.state.calendar(),'primary')}</div>`);}
 collectionView(){const s=this.state.s;return `<div class="notice-panel"><div class="row between"><div><h3>Energy shards · ${s.collected.length} / 50</h3><p>Five shards are hidden in each sector. Every five grants a Skill Point. Collect all fifty for the Reality core.</p></div>${button('Drones','open','data-page="drones"')}</div></div><div class="section-title">Reactor appearances · ${s.dust} stardust</div><div class="grid">${SKINS.map(d=>`<div class="card" style="text-align:center;--skin:${d[2]}"><div class="skin-preview"></div><span class="tag">${d[3]}</span><h3 style="margin-top:8px">${s.skins.includes(d[0])?d[1]:d[4]<0?'Undiscovered signal':d[1]}</h3><p>${d[0]==='gold'?'+2% all energy.':d[4]<0?'Explore the world to discover this core.':'A cosmetic signature for your reactor.'}</p>${button(s.skin===d[0]?'Equipped':s.skins.includes(d[0])?'Equip':d[4]<0?'Locked':d[4]+' ◇','skin',`data-id="${d[0]}"`,s.skin===d[0]||!s.skins.includes(d[0])&&(d[4]<0||s.dust<d[4]),'small')}</div>`).join('')}</div>`;}
 dronesView(){const s=this.state.s;return `<div class="notice-panel"><h3>Your floating crew · ${s.equipped.length} / ${s.slots} equipped</h3><p>Drones circle your focused plot. Fuse three copies into one improved drone; each evolution adds 50% to its base bonus. Up to ten evolutions per type.</p>${button('Extra slot · 50 tokens','droneslot','',s.slots>=3||s.tokens<50,'small')}</div><div class="grid">${DRONES.map((d,i)=>`<div class="card"><div class="icon" style="color:${d[2]}">⌘</div><h3>${d[0]}</h3><p>${d[1]} · bonus multiplier ${(1+s.droneLevels[i]*.5).toFixed(1)}×</p><div class="tag">${s.droneCopies[i]} COPIES · EVOLUTION ${s.droneLevels[i]}</div><div class="cardfooter">${button(d[3]+' ◇','dronebuy',`data-i="${i}"`,s.dust<d[3],'small')}${button(s.equipped.includes(i)?'Unequip':'Equip','droneequip',`data-i="${i}"`,s.droneCopies[i]<1,'small')}${button('Fuse 3','dronefuse',`data-i="${i}"`,s.droneCopies[i]<3||s.droneLevels[i]>=10,'small')}</div></div>`).join('')}</div>`;}
 rebirthView(){const s=this.state.s;return `<div class="rebirth-hero"><div class="metric-panel"><div class="eyebrow">CURRENT RUN</div><div class="metrics-row" style="margin-top:10px"><div class="mini-metric"><small>RUN ENERGY</small><strong>${this.state.fmt(s.run)}</strong></div><div class="mini-metric"><small>DISTRICTS</small><strong>${s.areas.length}</strong></div><div class="mini-metric"><small>MACHINE LEVELS</small><strong>${s.machines.reduce((a,b)=>a+b,0)}</strong></div><div class="mini-metric"><small>REBIRTHS</small><strong>${s.rebirths}</strong></div></div></div><div class="metric-panel"><div class="metric-label">REBIRTH REWARD</div><div class="metric-value gold" id="rebirthGain">+${this.state.fmt(this.state.rebirthGain)} cores</div><p>Permanent rebirth technology accelerates future facility runs.</p></div></div><div class="grid"><div class="card"><div class="eyebrow">WHAT WILL RESET</div><h3>Current facility run</h3><ul><li>Current energy and run earnings</li><li>Normal machine levels, except retained memory</li><li>Facility infrastructure and district access</li><li>Temporary boosts and challenges</li></ul></div><div class="card"><div class="eyebrow">WHAT YOU KEEP</div><h3>Permanent progress</h3><ul><li>Main skill tree and XP</li><li>Research, cosmetics and worker contracts</li><li>Quests, discoveries and lifetime records</li><li>Quantum cores and permanent upgrades</li></ul></div><div class="card"><div class="eyebrow">REBIRTH READY</div><h3 id="rebirthProgress">${this.state.fmt(s.run)} / ${this.state.fmt(this.state.rebirthRequirement)}</h3><div class="thin-bar"><i style="width:${Math.min(100,s.run/this.state.rebirthRequirement*100)}%"></i></div><p>Rebirth only when the permanent reward is worth resetting the current run.</p>${button('REBIRTH','rebirthconfirm','',s.run<this.state.rebirthRequirement,'primary')}</div></div><div class="section-title">ADVANCED PRESTIGE</div><div class="grid"><div class="card"><h3>Ascension · ${s.cycle}/10 cycle</h3><p>Complete ten rebirths in this cycle to gain 3 Singularity Shards and a permanent +200% energy bonus.</p>${button('Ascend','ascendconfirm','',s.cycle<10,'small')}</div><div class="card"><h3>New Reality · ${s.reality}</h3><p>Requires 3 ascensions, BREAK REALITY and Multiverse Access. Cosmetics and lifetime records remain.</p>${button('Enter New Reality','realityconfirm','',s.ascensions<3||!this.state.fx.breakReality||!this.state.fx.multiverse,'small')}</div></div>`;}
  challengesView(){const s=this.state.s;return `<div class="notice-panel"><h3>A new rule. One million energy.</h3><p>Starting resets current energy, machines, run earnings and boosts. Your skills remain. First clears grant 3 SP and +10% permanent energy; every clear grants 20 stardust.</p>${s.challenge?`<p class="mint">Active: ${s.challenge.id} · ${this.state.fmt(s.challenge.earned)} / 1M</p>${button('Abandon','abandon')}`:''}</div><div class="grid">${[['manual','Manual only','Machine production and automatic pulses are disabled.'],['machine','Machine only','Manual pulses are disabled. Start with one collector; requires Basic automation.'],['instability','Reactor instability','Machine production oscillates from 30% to 170%.'],['speed','Speed challenge','Reach 1M energy within 180 seconds.'],['branch','One branch','During the challenge, new main-tree research must stay within your existing branch. Start after a respec for a single-branch run.']].map(([id,name,desc])=>`<div class="card ${s.completedChallenges.includes(id)?'done':''}"><h3>${name}</h3><p>${desc}</p>${button('Begin challenge','challengeconfirm',`data-id="${id}"`,!!s.challenge||s.rebirths<1||(id==='branch'&&new Set(Object.keys(s.skills).filter(id=>NODE_MAP[id].tree==='main').map(id=>NODE_MAP[id].branch)).size>1))}</div>`).join('')}</div>`;}
 achievementsView(){const s=this.state.s;return `<div class="notice-panel"><h3>${s.achievements.length} / ${this.state.achDefs.length} achievements</h3><p>Each grants stardust and +0.5% permanent energy. Every five completed achievements grants a Skill Point.</p></div><div class="grid">${this.state.achDefs.map(a=>{const done=s.achievements.includes(a.id),v=Math.min(a.goal,a.value());return `<div class="card ${done?'done':''}"><div class="row between"><h3>${a.name}</h3><span class="mint">${done?'✓':'✧'}</span></div><p>${a.desc}</p><div class="progress-label"><span>${this.state.fmt(v)} / ${this.state.fmt(a.goal)}</span><span>${a.reward} ◇</span></div><div class="thin-bar"><i style="width:${v/a.goal*100}%"></i></div></div>`}).join('')}</div>`;}
 statsView(){const s=this.state.s,items=[['Current energy',s.energy],['Lifetime energy',s.lifetime],['Run energy',s.run],['Energy/sec',this.state.cps],['Interactions',s.stats.clicks],['Critical interactions',s.stats.criticals],['Highest pulse',s.stats.highest],['Machine levels',s.machines.reduce((a,b)=>a+b,0)],['Machines upgraded',s.stats.purchases],['Player level',this.state.level],['Skill Points earned',s.pointsEarned],['Nodes unlocked',Object.keys(s.skills).length],['Rebirths',s.rebirths],['Ascensions',s.ascensions],['Quantum cores',s.cores],['Singularity shards',s.shards],['Bosses defeated',s.stats.bosses],['Games completed',s.stats.games],['Quests completed',s.stats.quests],['Reactor skins',s.skins.length],['Drones owned',s.droneCopies.reduce((a,b)=>a+b,0)],['Time played',timeLabel(s.stats.time)],['Offline energy',s.stats.offline],['Areas discovered',s.discovered.length],['Energy shards',s.collected.length+' / 50'],['Secrets discovered',s.secrets.length],['Best memory round',s.stats.memory],['Fastest relay',s.stats.parkour?s.stats.parkour.toFixed(1)+'s':'—'],['Highest combo',s.stats.combo.toFixed(1)+'×'],['Realities',s.reality]];return `<div class="grid">${items.map(([k,v])=>`<div class="card"><div class="muted">${k}</div><div class="stat">${typeof v==='number'?this.state.fmt(v):v}</div></div>`).join('')}</div>`;}
 setting(label,key,options){const s=this.state.s.settings;return `<label class="settings-row"><span>${label}</span><select data-setting="${key}">${options.map(([v,n])=>`<option value="${v}" ${s[key]===v?'selected':''}>${n}</option>`).join('')}</select></label>`;}
 toggle(label,key){return `<label class="settings-row"><span>${label}</span><input type="checkbox" data-setting="${key}" ${this.state.s.settings[key]?'checked':''}></label>`;}
 range(label,key,min,max,step){return `<label class="settings-row"><span>${label}</span><input aria-label="${label}" type="range" data-setting="${key}" min="${min}" max="${max}" step="${step}" value="${this.state.s.settings[key]}"></label>`;}
 settingsView(){return `<div class="grid"><div class="card"><h3>Camera controls</h3><p>WASD pans the facility. Scroll or pinch to zoom. Middle-mouse drag pans and right-mouse drag rotates. Q / E also rotate the camera. Select buildings to manage them.</p>${this.toggle('Reduced motion','reduced')}${this.toggle('Show guidance','tutorial')}<p>Arrow keys also pan. Home returns to Headquarters. Escape closes the current building interface.</p></div><div class="card"><h3>Graphics</h3>${this.setting('Quality','quality',[['low','Low'],['medium','Medium'],['high','High'],['ultra','Ultra']])}${this.setting('FPS limit','fps',[[30,'30'],[60,'60'],[120,'120']])}${this.setting('Render distance','renderDistance',[[75,'75 m'],[150,'150 m'],[250,'250 m']])}${this.toggle('Energy particles','particles')}${this.toggle('Shadows','shadows')}${this.toggle('Dynamic lighting','lighting')}<p>Anti-aliasing is enabled. Quality controls render resolution. Motion blur is omitted for clear movement.</p></div><div class="card"><h3>Sound</h3>${this.toggle('Sound effects','sound')}${this.toggle('Ambient music','music')}${this.range('Master','master',0,1,.05)}${this.range('Sound effects','sfx',0,1,.05)}${this.range('Music','musicVolume',0,1,.05)}<p>Quiet ambient music and optional feedback for clicks and upgrades.</p></div><div class="card"><h3>Visual signature</h3>${this.setting('UI accent','accent',[['#3f7861','Forest'],['#416e82','Slate blue'],['#796489','Plum'],['#8b743c','Ochre']])}${this.setting('Machine finish','machineColor',[['#6f8fa5','Titanium'],['#bf815e','Copper'],['#849a71','Sage'],['#9982b2','Amethyst']])}${this.setting('Number format','notation',[['short','Compact (1.23M)'],['scientific','Scientific (1.23e6)']])}${button('Fullscreen','fullscreen','','','small')}</div><div class="card"><h3>Your save</h3><p>Autosaves every five seconds. Export a backup before moving folders or clearing browser data. Classic Nova Foundry v1 saves can be imported; transferable currency and XP are retained.</p><div class="toolbar">${button('Save now','save')}${button('Export','export')}${button('Import','importdialog')}</div>${button('Reset all progress','resetconfirm','','','danger small')}<p>Offline: ${Math.round(this.state.offlineEfficiency*100)}% efficiency · ${this.state.offlineHours}h maximum. Unlock Offline Production to earn while away.</p></div></div>`;}
 events(){document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)this.action(b.dataset);});document.addEventListener('change',e=>{const k=e.target.dataset.setting;if(!k)return;this.state.s.settings[k]=e.target.type==='checkbox'?e.target.checked:['fps','renderDistance','master','sfx','musicVolume','sensitivity'].includes(k)?Number(e.target.value):e.target.value;document.documentElement.style.setProperty('--accent',this.state.s.settings.accent);document.body.classList.toggle('reduced',this.state.s.settings.reduced);this.world.applySettings();this.world.sync();this.state.emit('audio-settings');this.state.save();});document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||!this.started)return;if(e.code==='Escape'&&this.opened&&!$('dialog').open)this.close();});$('dialog').addEventListener('cancel',()=>{this.world.paused=this.opened;this.machineIndex=null;});$('enter').addEventListener('click',()=>{this.started=true;this.world.paused=false;$('welcome').classList.add('hidden');if(this.state.pendingOffline){const o=this.state.pendingOffline;this.notice(`Welcome back · ${timeLabel(o.seconds)} away · +${this.state.fmt(o.amount)} energy`);this.state.pendingOffline=null;}this.state.emit('audio-settings');this.state.save();});let stickActive=false;const stick=$('stick');stick.addEventListener('pointerdown',e=>{stickActive=true;stick.setPointerCapture(e.pointerId);move(e);});const move=e=>{if(!stickActive)return;const r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/40,y=(e.clientY-r.top-r.height/2)/40,l=Math.max(1,Math.hypot(x,y));this.world.moveStick={x:x/l,y:y/l};$('stickKnob').style.transform=`translate(${x/l*30}px,${y/l*30}px)`;};stick.addEventListener('pointermove',move);const stop=()=>{stickActive=false;this.world.moveStick={x:0,y:0};$('stickKnob').style.transform='';};stick.addEventListener('pointerup',stop);stick.addEventListener('pointercancel',stop);$('touchJump').addEventListener('pointerdown',e=>{e.preventDefault();this.world.keys.Space=true;});for(const event of ['pointerup','pointercancel'])$('touchJump').addEventListener(event,()=>this.world.keys.Space=false);$('touchInteract').addEventListener('click',()=>this.world.interact());}
 async action(d){const a=d.action,id=d.id,i=Number(d.i),s=this.state.s;if(a==='open'){this.open(d.page);return;}if(a==='close'){this.close();return;}if(a==='closedialog'){this.closeDialog();return;}if(a==='maphome'){this.activities.clear();this.world.teleport('lab');return;}if(a==='mapoverview'){this.activities.clear();this.world.overview();return;}if(a==='mapzoom'){this.world.zoom(Number(d.dir)>0?1/1.2:1.2);return;}if(a==='node'){this.selected=id;$('inspector').innerHTML=this.inspector();document.querySelectorAll('.node').forEach(b=>b.classList.toggle('chosen',b.dataset.id===id));return;}if(a==='requiredskill'){this.closeDialog();this.treeType='main';this.branch='explore';this.selected=id;this.transform={x:20,y:20,scale:1};this.open('tree');return;}if(a==='skillbuy'){this.state.skillBuy(id);return;}if(a==='treetype'){this.treeType=id;this.selected=id==='main'?(this.branch==='cross'?'cross-0':this.branch+'-0'):NODES.find(n=>n.tree===id).id;this.transform={x:20,y:20,scale:id==='main'?1:.8};this.render();return;}if(a==='branch'){this.branch=id;this.selected=id==='cross'?'cross-0':id+'-0';this.transform={x:20,y:20,scale:1};this.render();return;}if(a==='treefit'){this.fitTree();return;}if(a==='zoom'){this.zoom(Number(d.dir)>0?1.2:1/1.2);return;}
 if(a==='respec'){this.dialog(`<h2>Rethink your path?</h2><p>Refund all main-tree Skill Points. Quantum, Ascension and Mastery trees remain. World access is recalculated and you return to Origin. XP for previously discovered nodes cannot be earned again.</p><p>${s.respecs?'Cost: 25 stardust.':'Your first respec is free.'}</p><div class="actions">${button('Keep my path','closedialog')}${button('Respec main tree','respecdo','',s.respecs>0&&s.dust<25,'primary')}</div>`);return;}if(a==='respecdo'){this.state.respec();this.closeDialog();this.render();return;}
 if(a==='travel'){if(!s.areas.includes(id))return;this.activities.clear();this.world.teleport(id);this.close();return;}
 if(a==='machinebuy'){this.state.buyMachine(i,d.n==='max'?'max':Number(d.n));if(this.machineIndex!==null)this.showMachine();else this.render();return;}if(a==='bulk'){this.buy=d.n==='max'?'max':Number(d.n);this.render();return;}if(a==='facility'){this.state.facilityBuy(i);this.render();return;}if(a==='researchbuy'){this.state.startResearch(i);this.render();return;}
 if(a==='startgame'){if(s.lifetime<1000||id==='boss'&&!s.rebirths)return;this.close();this.activities.start(id);return;}if(a==='return'){this.closeDialog();this.close();this.activities.leave();return;}if(a==='tokenboost'){const costs={all:10,click:8,xp:15};if(s.tokens<costs[id])return;s.tokens-=costs[id];this.state.addBoost(id,id==='click'?5:2,id==='click'?60:300);this.notice('Boost activated');this.render();return;}
 if(a==='mission'){this.state.claimMission(id);this.render();return;}if(a==='npcclaim'){this.state.npcClaim(id);this.closeDialog();return;}if(a==='daily'){this.state.dailyClaim();if($('dialog').open)this.closeDialog();if(this.opened)this.render();return;}
 if(a==='markettrade'){if(id==='dust'&&s.energy>=10000){s.energy-=10000;s.dust+=1;this.notice('Trade complete · +1 stardust');}else if(id==='tokens'&&s.dust>=5){s.dust-=5;s.tokens+=10;this.notice('Trade complete · +10 arcade tokens');}else if(id==='energy'&&s.tokens>=10){s.tokens-=10;s.energy+=50000;this.notice('Trade complete · +50K energy');}this.state.recompute();this.state.save();this.render();return;}if(a==='skin'){this.state.buySkin(id);this.render();return;}if(a==='outfit'){s.outfit=i;this.render();return;}if(a==='dronebuy'){this.state.droneBuy(i);this.render();return;}if(a==='dronefuse'){this.state.droneFuse(i);this.render();return;}if(a==='droneequip'){if(s.equipped.includes(i))s.equipped=s.equipped.filter(n=>n!==i);else if(s.droneCopies[i]&&s.equipped.length<s.slots)s.equipped.push(i);else this.notice('All slots are full. Unequip a drone first.');this.world.sync();this.render();return;}if(a==='droneslot'&&s.tokens>=50&&s.slots<3){s.tokens-=50;s.slots++;this.render();return;}
 if(a==='qtree'||a==='atree'){this.treeType=a==='qtree'?'quantum':'ascension';this.selected=a==='qtree'?'q-0':'a-0';this.transform={x:0,y:0,scale:.7};this.open('tree');return;}
 if(['rebirthconfirm','ascendconfirm','realityconfirm'].includes(a)){const which=a.replace('confirm',''),desc=which==='rebirth'?'Reset the current facility and earn '+this.state.fmt(this.state.rebirthGain)+' Quantum Cores? Main skills, research, cosmetics and lifetime records remain.':which==='ascend'?'Reset this ascension cycle, quantum research, machine levels and research projects? Gain 3 Singularity Shards and +200% permanent energy.':'Reset all progression trees and the facility? Cosmetics, achievements, settings and lifetime records remain. Gain a New Reality multiplier.';this.dialog(`<h2>${which==='rebirth'?'Reignite your universe?':which==='ascend'?'Ascend beyond the facility?':'Create a New Reality?'}</h2><p>${desc}</p><div class="actions">${button('Keep building','closedialog')}${button('Confirm '+which,which,'',false,'primary')}</div>`);return;}
 if(a==='rebirth'){if(s.run<this.state.rebirthRequirement)return;this.closeDialog();this.close();this.world.paused=true;this.state.resetting=true;$('transition').classList.remove('hidden');$('transitionText').textContent='The universe is holding its breath.';this.state.emit('sound',90);setTimeout(()=>{$('transitionText').textContent='+'+this.state.performRebirth()+' QUANTUM CORES';},2100);setTimeout(()=>{$('transition').classList.add('hidden');this.state.resetting=false;this.world.paused=false;},3300);return;}
 if(a==='ascend'){if(this.state.ascend()){this.close();this.world.sync();this.notice('ASCENSION COMPLETE · +3 Singularity Shards');}return;}if(a==='reality'){if(this.state.newReality()){this.close();this.world.sync();}return;}
 if(a==='challengeconfirm'){this.dialog(`<h2>Begin this challenge?</h2><p>Current energy, machine levels, run earnings and boosts reset. Earn 1M energy under the new rule to complete it.</p><div class="actions">${button('Cancel','closedialog')}${button('Begin','challengedo',`data-id="${id}"`,false,'primary')}</div>`);return;}if(a==='challengedo'){this.state.challengeStart(id);this.close();return;}if(a==='abandon'){s.challenge=null;this.render();return;}
 if(a==='save'){this.state.save();this.notice(this.state.storageFailed?'Export a backup to keep your progress.':'Universe saved');return;}if(a==='export'){this.state.save();this.dialog(`<h2>Back up your universe.</h2><p>Download or copy this save before moving to another browser.</p><textarea id="saveText" aria-label="Save text"></textarea><div class="actions">${button('Copy','copysave')}${button('Download JSON','downloadsave')}${button('Done','closedialog','','','primary')}</div>`);$('saveText').value=JSON.stringify(s);return;}
 if(a==='copysave'){try{await navigator.clipboard.writeText($('saveText').value);this.notice('Save copied');}catch{$('saveText').select();this.notice('Save selected. Press Ctrl+C / Cmd+C.');}return;}if(a==='downloadsave'){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));link.href=url;link.download='Nova-Foundry-3D-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);return;}
 if(a==='importdialog'){this.dialog(`<h2>Restore your universe.</h2><p>Paste a 3D save or a Classic Nova Foundry v1 export. Validated data replaces your current progress; a local backup is kept.</p><textarea id="saveText" aria-label="Save to import"></textarea><p id="importError" class="gold"></p><div class="actions">${button('Cancel','closedialog')}${button('Import','importdo','','','primary')}</div>`);return;}if(a==='importdo'){try{this.activities.clear();this.activities.clearEvent();this.state.import($('saveText').value);this.close();this.world.sync();this.notice('Save restored');}catch(e){$('importError').textContent=e.message;}return;}
 if(a==='resetconfirm'){this.dialog(`<h2>Delete all local progress?</h2><p>This removes all 3D progression. Export a backup first if you want to keep it. Type RESET to confirm.</p><input type="text" id="resetText" aria-label="Reset confirmation"><div class="actions">${button('Cancel','closedialog')}${button('Delete progress','resetdo','','','danger')}</div>`);return;}if(a==='resetdo'){if($('resetText').value!=='RESET')return;this.activities.clear();this.activities.clearEvent();this.state.s=initial();this.state.recompute();this.state.save();this.world.sync();this.world.teleport('lab');this.close();this.notice('A new universe begins.');return;}
 if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{this.notice('Fullscreen unavailable in this browser.');}return;}
 }
 paint(){const s=this.state.s;this.displayEnergy+=(s.energy-this.displayEnergy)*.3;if(Math.abs(this.displayEnergy-s.energy)<1)this.displayEnergy=s.energy;$('energy').textContent=this.state.fmt(this.displayEnergy);$('production').textContent=this.state.fmt(this.state.cps);$('dust').textContent=this.state.fmt(s.dust);$('cores').textContent=this.state.fmt(s.cores);$('points').textContent=this.state.fmt(s.points);$('playerLevel').textContent='LEVEL '+this.state.level;$('combo').textContent=(1+this.state.combo/100*(2+(this.state.fx.combo||0))).toFixed(1)+'× pulse';const l=this.state.level,base=35*(l-1)**2,next=35*l*l;$('xpBar').style.width=(s.xp-base)/(next-base)*100+'%';$('menuBalance').textContent=this.state.fmt(s.energy)+' ϟ   ·   '+s.points+' SP';$('boosts').innerHTML=s.boosts.filter(b=>b.end>Date.now()).map(b=>`<span class="boost">${b.mult}× ${b.type} · ${timeLabel((b.end-Date.now())/1000)}</span>`).join('');
 let label='YOUR FIRST SPARK',objective='Click the energy core to get started.',percent=Math.min(100,s.stats.clicks/5*100);if(s.stats.clicks>=5&&!this.state.fx.automation){label='A PATH OF YOUR OWN';objective='Open Skills and choose Basic automation to start producing energy automatically.';percent=100;}else if(this.state.fx.automation&&!s.machines[0]){label='LET THE MACHINES WORK';objective='Click the collector in the upper-right plot. Build it for 20 energy.';percent=Math.min(100,s.energy/20*100);}else if(s.machines[0]){const a=AREAS.find(a=>!s.areas.includes(a.id));label=a?'YOUR NEXT SECTOR':'THE NEXT BEGINNING';objective=a?`${a.name} · ${this.state.fmt(a.need)} run energy + ${NODES.find(n=>n.effects[a.flag])?.name}`:`Rebirth at ${this.state.fmt(this.state.rebirthRequirement)} run energy.`;percent=Math.min(100,s.run/(a?a.need:this.state.rebirthRequirement)*100);}if(this.activities.active){label='ARCADE CHAMBER';objective='Play directly with your mouse or touch. Use Leave minigame to return.';}if(s.challenge){label='CHALLENGE / '+s.challenge.id.toUpperCase();objective=this.state.fmt(s.challenge.earned)+' / 1M energy'+(s.challenge.id==='speed'?' · '+timeLabel(Math.max(0,180-(Date.now()-s.challenge.start)/1000)):'');}if(!s.settings.tutorial&&!this.activities.active){label='NOVA FOUNDRY';objective=this.state.fmt(s.lifetime)+' lifetime energy · '+s.discovered.length+' sectors discovered';}$('objectiveLabel').textContent=label;$('objectiveText').textContent=objective;$('objectiveBar').style.width=percent+'%';
 const r=this.world.current;$('interaction').style.left=Math.min(innerWidth-270,this.world.pointer.x+18)+'px';$('interaction').style.top=Math.min(innerHeight-140,this.world.pointer.y+18)+'px';$('interaction').style.opacity=r&&!this.opened&&this.started&&!$('dialog').open?'1':'0';$('reticle').classList.toggle('ready',!!r);if(r){$('interactLabel').textContent=r.label;$('interactSub').textContent=r.action==='core'?'+'+this.state.fmt(this.state.manual*(1+this.state.combo/100*(2+(this.state.fx.combo||0))))+' energy · click to collect':r.action==='machine'?'Level '+this.state.s.machines[r.data]+' · Click to manage':r.action==='locked'?'Locked district · Click for requirements':'Click to manage';}
 const a=this.activities.active;$('activityHud').classList.toggle('hidden',!a);$('leaveGame').classList.toggle('hidden',!a);if(a){$('activityHud').innerHTML=a.kind==='memory'?`STABILISATION · Round <strong>${a.round}/8</strong><br>${a.phase==='input'?'Your turn · Repeat the sequence':'Watch the panels'}`:a.kind==='boss'?`${a.warning?'⚠ Click SHIELD now':a.name}<br><strong>${this.state.fmt(Math.max(0,a.hp))}</strong> / ${this.state.fmt(a.max)} HP · ${Math.ceil((a.end-Date.now())/1000)}s`:a.kind.toUpperCase()+` · <strong>${Math.ceil((a.end-Date.now())/1000)}s</strong>`+(a.kind==='parkour'?` · ${a.step}/12 relays`:` · ${a.score} points`);}
 const event=this.activities.event;$('eventHud').classList.toggle('hidden',!event);if(event)$('eventHud').textContent=event.kind.toUpperCase()+' / ORIGIN LAB · '+timeLabel((event.end-Date.now())/1000)+(event.kind!=='surge'?' · '+event.left+' remaining':'');
 if(this.opened&&this.page==='rebirth'){$('rebirthGain').textContent='+'+this.state.fmt(this.state.rebirthGain)+' ⬡';$('rebirthProgress').textContent=this.state.fmt(s.run)+' / '+this.state.fmt(this.state.rebirthRequirement);const b=document.querySelector('[data-action="rebirthconfirm"]');if(b)b.disabled=s.run<this.state.rebirthRequirement;}
 if(this.opened&&this.page==='tree'){const n=NODE_MAP[this.selected],cur=n.tree==='quantum'?'cores':n.tree==='ascension'?'shards':'points',b=document.querySelector('[data-action="skillbuy"]');if(b)b.disabled=!this.state.available(n)||s[cur]<this.state.nodeCost(n);}
 document.querySelectorAll('[data-action="machinebuy"]').forEach(b=>{const i=Number(b.dataset.i),n=b.dataset.n==='max'?'max':Number(b.dataset.n),q=this.state.quote(i,n);b.disabled=!this.state.fx.automation||!s.areas.includes(MACHINES[i].area)||s.energy<q.cost||q.n<1;if(this.machineIndex!==null)b.textContent='×'+(n==='max'?'MAX':n)+' · '+this.state.fmt(q.cost)+' ϟ';else if(n==='max')b.textContent='Buy ×'+q.n;});
 document.querySelectorAll('[data-action="mission"]').forEach(b=>{const m=this.state.missions().find(m=>m[0]===b.dataset.id);if(m)b.disabled=s.quests.claims.includes(m[0])||(s.quests[m[1]][m[2]]||0)<m[3];});
 if(s.researchJob)document.querySelectorAll('[data-research-time]').forEach(el=>el.textContent=timeLabel(Math.max(0,(s.researchJob.end-Date.now())/1000)));
 this.drawMap();
 }
 drawMap(){const c=$('minimap'),ctx=c.getContext('2d');ctx.clearRect(0,0,190,110);const scale=1.35,ox=95,oy=65;for(const a of AREAS){ctx.fillStyle=this.state.s.areas.includes(a.id)?'#335b60':'#243541';ctx.fillRect(ox+a.x*scale-12,oy+a.z*scale-12,24,24);ctx.strokeStyle=this.state.s.areas.includes(a.id)?'#82cab5':'#415460';ctx.strokeRect(ox+a.x*scale-12,oy+a.z*scale-12,24,24);}if(this.state.fx.scanner&&!this.world.arena){ctx.fillStyle='#f2d382';for(const m of this.world.shards)if(m.visible)ctx.fillRect(ox+m.position.x*scale-1,oy+m.position.z*scale-1,2,2);}if(!this.world.arena){ctx.fillStyle='#edfff6';ctx.beginPath();ctx.arc(ox+this.world.player.x*scale,oy+this.world.player.z*scale,3,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#a2c2ca';ctx.font='8px Arial';ctx.fillText('FACILITY / '+this.state.s.areas.length+' SECTORS',10,103);}
 update(dt){this.uiTimer+=dt;if(this.uiTimer>.12){this.uiTimer=0;this.paint();}}
}
